import{isModelOptions,normalizeModelOptions}from"#models/options.js";const AGENT_TOOL_MODELS=Symbol.for(`eve.agent-tool-models`);function parseAgentToolModels(e){if(!isModelOptions(e))throw TypeError(`agent({ models }) requires a record of description strings, keyed by AI Gateway model ID, or { model, description, reasoning?, modelContextWindowTokens?, modelOptions? } entries.`);let t=normalizeModelOptions(e);if(t.length===0)throw TypeError(`agent({ models }) requires at least one model.`);return new Map(t.map(e=>[e.key,e]))}function attachAgentToolModels(e,t){return Object.defineProperty(e,AGENT_TOOL_MODELS,{configurable:!1,enumerable:!1,value:t,writable:!1}),e}function readAgentToolModels(e){if(typeof e==`object`&&e)return e[AGENT_TOOL_MODELS]}export{attachAgentToolModels,parseAgentToolModels,readAgentToolModels};