import{createHash}from"node:crypto";import{requireClearance}from"#harness/clearance.js";function admitWorkflowTask(e,t){requireClearance(t,e.callId);let n={...e,clearedBy:t.clearedBy};return{...n,admission:{callId:t.callId,fingerprint:fingerprint(n)}}}function hasWorkflowAdmission(e){return e.admission?.callId===e.callId&&e.admission.fingerprint===fingerprint(e)}function fingerprint(e){return createHash(`sha256`).update(stableJson([e.callId,e.toolName,e.workflowId,e.entry,e.input,e.executeInput,e.clearedBy])).digest(`hex`)}function stableJson(e){return JSON.stringify(e,(e,t)=>typeof t!=`object`||!t||Array.isArray(t)?t:Object.fromEntries(Object.keys(t).sort().map(e=>[e,t[e]])))}export{admitWorkflowTask,hasWorkflowAdmission};